def compute(vars):
    beginning = vars["v1"]
    ending = vars["v2"]
    change = ending - beginning

    return {
        "value": change,
        "trace": {
            "beginning_balance": beginning,
            "ending_balance": ending,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
